mapper.delete:
        delete from ${database.prefix.goods}hou_goods_article_like
		where like_user = #{param.likeUser}
		  and like_id = #{param.likeId}

mapper.select:
        select like_id
		from ${database.prefix.goods}hou_goods_article_like
		where like_user = #{param.userId}
		and liked_id = #{param.likedId}
		and like_type = #{param.likeType}
